#include <omp.h>
#include <vector>
#include <array>

struct Point {
   double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    // Initialize the output bins to zero
    bins.fill(0);

    // Parallel counting with private local counters
    #pragma omp parallel
    {
        // Each thread has its own local counts for the four quadrants
        size_t local[4] = {0, 0, 0, 0};

        // Distribute points among threads
        #pragma omp for schedule(static) nowait
        for (size_t i = 0; i < points.size(); ++i) {
            const Point &p = points[i];
            int q = -1; // -1 indicates a point on an axis

            if (p.x > 0 && p.y > 0) {
                q = 0; // Quadrant I
            } else if (p.x < 0 && p.y > 0) {
                q = 1; // Quadrant II
            } else if (p.x < 0 && p.y < 0) {
                q = 2; // Quadrant III
            } else if (p.x > 0 && p.y < 0) {
                q = 3; // Quadrant IV
            }

            if (q != -1) {
                ++local[q];
            }
        }

        // Merge local counts into the shared bins array
        #pragma omp critical
        {
            for (int i = 0; i < 4; ++i) {
                bins[i] += local[i];
            }
        }
    }
}
